            Async\await($this->load_markets());
        }
        Async\await($this->authenticate());
        $messageHash = 'orders';
        $channel = 'orders.';
        $symbolResolved = ($symbol !== null) ? $this->symbol($symbol) : $symbol;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $channel .= $market['id'];
            $messageHash .= ':' . $symbolResolved;
        } else {
            $channel .= 'ALL';
        }
        $url = $this->get_ws_url();
        $request = array(
            'jsonrpc' => '2.0',
            'method' => 'subscribe',
            'params' => array(
