        $limitResolved = $limit;
        if ($this->newUpdates) {
            $limitResolved = $orders->getLimit($symbolResolved, $limit);
        }
        return $this->filter_by_symbol_since_limit($orders, $symbolResolved, $since, $limitResolved, true);
    }

